// A second batch of video games, November 2026: games from 2005 on that at least one game developer in seven would
// know (the owner's bar), in the spirit of Rain World, Pratfall, Peak, Ravenswatch and Far Far West. Studios and dates
// checked against the Steam store (original release years, not ports); studios' countries from their own pages and
// press. Merged by scripts/add-works-2026-11b.mjs, which spreads their `from` dates after the first batch's.
// Clues written for the game; no quotes; items and locations only where sure.
const clue = (name, description, src) => ({ name, description, ...(src ? { src } : {}) });
const PC = ['PC'];
const PCC = ['PC', 'PlayStation', 'Xbox'];
const ALL = ['PC', 'PlayStation', 'Xbox', 'Nintendo'];
const ALLM = [...ALL, 'Mobile'];

/** One game: the facts, then its clues. `audio` is [clue, search query]. */
const G = (id, name, aliases, year, genres, studio, creator, origin, format, platforms, characters, themes, credits, emoji, audio, icon, colors, extra = {}) => ({
  id: `g-${id}`, name, ...(aliases.length ? { aliases } : {}), year, genres, studio, creator, origin, format, platforms, characters, themes, credits,
  cover: { wiki: extra.wiki ?? name }, audio: { clue: audio[0], query: audio[1] }, emoji, visual: { icon, colors },
  ...(extra.fandom ? { fandom: extra.fandom } : {}), ...(extra.item ? { item: extra.item } : {}), ...(extra.location ? { location: extra.location } : {}),
});

